import functools
class Solution:
    def maxValueSegments(self, nums1, nums0):
        segs = ['1'*a + '0'*b for a, b in zip(nums1, nums0)]
        segs.sort(key=functools.cmp_to_key(lambda a, b: (a+b < b+a) - (a+b > b+a)))
        MOD = 10**9 + 7
        ans = 0
        for ch in ''.join(segs):
            ans = (ans * 2 + (ch == '1')) % MOD
        return ans

