        vector<string> segs(n);
        for (int i = 0; i < n; i++) {
            segs[i] = string(nums1[i], '1') + string(nums0[i], '0');
        }
        sort(segs.begin(), segs.end(), [](const string& a, const string& b) {
            return a + b > b + a;
        });
        const long long MOD = 1e9 + 7;
        long long ans = 0;
        for (auto& s : segs)
            for (char c : s) ans = (ans * 2 + (c == '1')) % MOD;
        return (int) ans;
    }
};

