class Solution {
    public int maxValueSegments(int[] nums1, int[] nums0) {
        int n = nums1.length;
        String[] segs = new String[n];
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < nums1[i]; j++) sb.append('1');
            for (int j = 0; j < nums0[i]; j++) sb.append('0');
            segs[i] = sb.toString();
        }
        Arrays.sort(segs, (a, b) -> (a + b).compareTo(b + a) * -1);
        final long MOD = 1_000_000_007L;
        long ans = 0;
        for (String s : segs)
            for (char c : s.toCharArray()) ans = (ans * 2 + (c == '1' ? 1 : 0)) % MOD;
        return (int) ans;
    }
}

