class Solution:
    def maxValueSegments(self, nums1, nums0):
        import functools
        segs = list(zip(nums1, nums0))
        def cmp(a, b):
            lhs = a[0] * ((1 << b[1]) - 1)
            rhs = b[0] * ((1 << a[1]) - 1)
            return -1 if lhs > rhs else (1 if lhs < rhs else 0)
        segs.sort(key=functools.cmp_to_key(cmp))
        MOD = 10**9 + 7
        ans = 0
        for ones, zeros in segs:
            ans = (ans * pow(2, ones, MOD) + pow(2, ones, MOD) - 1) % MOD
            ans = ans * pow(2, zeros, MOD) % MOD
        return ans

