class Solution {
public:
    long long pw(long long b, long long e, long long m) {
        long long r = 1; b %= m;
        while (e) { if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    int maxValueSegments(vector<int>& nums1, vector<int>& nums0) {
        int n = nums1.size();
        vector<pair<int,int>> segs(n);
        for (int i = 0; i < n; i++) segs[i] = {nums1[i], nums0[i]};
        sort(segs.begin(), segs.end(), [](pair<int,int> a, pair<int,int> b) {
            // compare ones_a*(2^zb - 1) vs ones_b*(2^za - 1) approximately via long double logs,
            // exact via __builtin big values is complex; use long double (safe for these ranges)
            long double la = (long double)a.first * (long double)b.second * 0.6931471805599453L;
            long double lb = (long double)b.first * (long double)a.second * 0.6931471805599453L;
            return la > lb;
        });
        const long long MOD = 1e9 + 7;
        long long ans = 0;
        for (auto& [ones, zeros] : segs) {
            long long p = pw(2, ones, MOD);
            ans = (ans * p + p - 1) % MOD;
            ans = ans * pw(2, zeros, MOD) % MOD;
        }
        return (int) ans;
    }
};

