class Solution {
    private long pw(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    public int maxValueSegments(int[] nums1, int[] nums0) {
        int n = nums1.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        final int[] a1 = nums1, a0 = nums0;
        Arrays.sort(idx, (i, j) -> {
            java.math.BigInteger lhs = java.math.BigInteger.valueOf(a1[i])
                .multiply(java.math.BigInteger.TWO.pow(a0[j]).subtract(java.math.BigInteger.ONE));
            java.math.BigInteger rhs = java.math.BigInteger.valueOf(a1[j])
                .multiply(java.math.BigInteger.TWO.pow(a0[i]).subtract(java.math.BigInteger.ONE));
            return rhs.compareTo(lhs);
        });
        final long MOD = 1_000_000_007L;
        long ans = 0;
        for (int k = 0; k < n; k++) {
            int i = idx[k];
            long p = pw(2, a1[i], MOD);
            ans = (ans * p + p - 1) % MOD;
            ans = ans * pw(2, a0[i], MOD) % MOD;
        }
        return (int) ans;
    }
}

