var maxValueSegments = function(nums1, nums0) {
    const segs = nums1.map((a, i) => [a, nums0[i]]);
    segs.sort((a, b) => {
        const la = a[0] * (Math.pow(2, b[1]) - 1);
        const lb = b[0] * (Math.pow(2, a[1]) - 1);
        return lb - la;
    });
    const MOD = 1e9 + 7;
    const pw = (b, e) => { let r = 1; b %= MOD; while (e > 0) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e = Math.floor(e / 2); } return r; };
    let ans = 0;
    for (const [ones, zeros] of segs) {
        const p = pw(2, ones);
        ans = (ans * p + p - 1) % MOD;
        ans = ans * pw(2, zeros) % MOD;
    }
    return ans;
};
